(7649659, 1244013, 114285, '<td valign="top">Ohhh shame about the DQ, youve dropped out of the top three now, maybe your FS or HDR will propel you forward.</td>', 'Ohhh shame about the DQ, youve dropped out of the top three now, maybe your FS or HDR will propel you forward.', '2020-01-07 01:56:54.000000', NULL, 0),
(7649662, 1244013, 3306, '<td valign="top">In defense of my DQ, I had submitted this picture to the site council prior to its submission as allowed in the rules for advice about if the texture as used was allowable. I received a reply that stated it was OK.</td>', 'In defense of my DQ, I had submitted this picture to the site council prior to its submission as allowed in the rules for advice about if the texture as used was allowable. I received a reply that stated it was OK.', '2020-01-07 06:25:31.000000', NULL, 0),
(7649680, 1244013, 35078, '<td valign="top">Sorry about the disq. I don''t quite follow what happened? I had a 3rd place pic disq last week. Unfortunately I cropped it, which wasn''t allowed. Well at least my one in this challenge moved from 3rd to 2nd. Unfortunately at the cost of your first :( Good luck for the next one and a happy new year to you.</td>', 'Sorry about the disq. I don''t quite follow what happened? I had a 3rd place pic disq last week. Unfortunately I cropped it, which wasn''t allowed. Well at least my one in this challenge moved from 3rd to 2nd. Unfortunately at the cost of your first :( Good luck for the next one and a happy new year to you.', '2020-01-07 12:29:25.000000', NULL, 0),
(7649683, 1244013, 109363, '<td valign="top">Lawrence,<br/>Hey, i was really enjoying this neck-neck-neck competition for third place in the points and ribbon lineup ... so i was shocked to see the DQ ... it did not look like a composite to me, sorry about that... i guess it is all down to the Dec FS and HDR... ;0</td>', 'Lawrence,Hey, i was really enjoying this neck-neck-neck competition for third place in the points and ribbon lineup ... so i was shocked to see the DQ ... it did not look like a composite to me, sorry about that... i guess it is all down to the Dec FS and HDR... ;0', '2020-01-07 14:37:04.000000', NULL, 0),
